const byId=id=>document.getElementById(id);
const labels={'new':'Pending',contacted:'Pending',accepted:'Confirmed',denied:'Denied',completed:'Completed'};
const normalStatus=value=>value==='contacted'?'new':value;
const reasonLabels={'prescription-collection':'Prescription pickup','prescription-enquiry':'Prescription activation','medicine-advice':'Medication question','refill-enquiry':'Refill inquiry','general-visit':'General visit'};
let csrf='';let requests=[];let statusFilter='all';let activeRequest=null;let busy=false;let sessionTimer;
let messaging={mode:'preview',sms:false};let decisionTimesLoading=false;let decisionSequence=0;
const smsLabels={pending:'Waiting',preview:'Preview only',not_configured:'Setup needed',not_consented:'No SMS permission',sending:'Sending',queued:'Queued',sent:'Sent to carrier',delivered:'Delivered',failed:'Failed',unknown:'Delivery uncertain'};
const message=(id,text)=>byId(id).textContent=text;
async function api(url,options={},retry=true){
  const response=await fetch(url,{credentials:'same-origin',cache:'no-store',...options,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,...options.headers}});
  let data;try{data=await response.json();}catch{throw new Error('The admin service is unavailable. Please check the backend is running.');}
  if(response.status===403&&retry&&options.method&&options.method!=='GET'){const sessionResponse=await fetch('/api/session',{credentials:'same-origin',cache:'no-store'});if(sessionResponse.ok){const fresh=await sessionResponse.json();csrf=fresh.csrf;return api(url,options,false);}}
  if(response.status===401&&url!=='/api/login'){showLogin();throw new Error('Your session has ended. Please sign in again.');}
  if(!response.ok)throw new Error(data.error||'The request could not be completed.');return data;
}
function showLogin(){clearInterval(sessionTimer);requests=[];activeRequest=null;statusFilter='all';decisionSequence++;byId('request-search').value='';byId('requests-list').replaceChildren();byId('request-message-list').replaceChildren();byId('request-dialog').close();for(const id of ['request-dialog-title','request-dialog-reference','detail-phone','detail-reason','detail-date','detail-visit-time','detail-current-status','decision-sms-body'])message(id,'');byId('denial-reason').value='';byId('detail-phone').removeAttribute('href');byId('admin-workspace').hidden=true;byId('admin-login').hidden=false;byId('admin-password').value='';document.title='Staff Sign In · Fort Sam Houston Community Pharmacy';document.dispatchEvent(new Event('admin:signed-out'));}
function showWorkspace(username){byId('admin-login').hidden=true;byId('admin-workspace').hidden=false;byId('requests-view').hidden=false;byId('website-view').hidden=true;byId('reviews-view').hidden=true;document.dispatchEvent(new Event('admin:signed-in'));for(const button of document.querySelectorAll('[data-admin-view]')){const current=button.dataset.adminView==='requests';button.classList.toggle('active',current);if(current)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');}message('admin-breadcrumb','Visit requests');byId('signed-in-user').textContent=username;document.title='Visit Requests · Fort Sam Houston Community Pharmacy Admin';clearInterval(sessionTimer);sessionTimer=setInterval(()=>{api('/api/visits?background=1').then(data=>{requests=data.visits;renderRequests();}).catch(error=>message('admin-feedback',error.message));},60000);}
function formattedDate(value,options){return new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',...options}).format(new Date(value));}
function cell(text,className){const element=document.createElement('td');if(className)element.className=className;element.textContent=text;return element;}
function renderRequests(){
  for(const status of ['new','accepted','denied'])message('stat-'+status,requests.filter(item=>normalStatus(item.status)===status).length);
  message('stat-total',requests.length);message('nav-new-count',requests.filter(item=>normalStatus(item.status)==='new').length);message('inbox-count',requests.length+' '+(requests.length===1?'request':'requests'));
  const query=byId('request-search').value.trim().toLowerCase();
  const visible=requests.filter(item=>(statusFilter==='all'||normalStatus(item.status)===statusFilter)&&(!query||[item.name,item.phone,item.reference,reasonLabels[item.reason],item.visitDate||'',item.visitTime||''].join(' ').toLowerCase().includes(query)));
  for(const button of document.querySelectorAll('[data-status-filter]'))button.setAttribute('aria-pressed',String(button.dataset.statusFilter===statusFilter));
  const list=byId('requests-list');list.replaceChildren();
  for(const item of visible){
    const row=document.createElement('tr');const visitorCell=cell('');const visitor=document.createElement('div');visitor.className='visitor-cell';
    const initials=document.createElement('span');initials.className='visitor-initials';initials.textContent=item.name.split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0]).join('').toUpperCase();initials.setAttribute('aria-hidden','true');
    const info=document.createElement('div');info.className='visitor-info';const name=document.createElement('strong');name.textContent=item.name;const phone=document.createElement('a');phone.href='tel:'+item.phone.replace(/[^+\d]/g,'');phone.textContent=item.phone;info.append(name,phone);visitor.append(initials,info);visitorCell.append(visitor);
    const dateCell=cell('','received-cell');const date=document.createElement('span');date.className='received-date';date.textContent=formattedDate(item.createdAt,{day:'numeric',month:'short'});const time=document.createElement('span');time.className='received-time';time.textContent=formattedDate(item.createdAt,{hour:'2-digit',minute:'2-digit'});dateCell.append(date,time);
    const requested=cell('','requested-cell');const requestedDate=document.createElement('span');requestedDate.className='received-date';requestedDate.textContent=item.visitDate?formattedDate(item.visitDate+'T12:00:00Z',{day:'numeric',month:'short',year:'numeric'}):'Not supplied';const requestedTime=document.createElement('span');requestedTime.className='received-time';requestedTime.textContent=item.visitTime?item.visitTime+' · Central Time':'Older request';requested.append(requestedDate,requestedTime);
    const statusCell=cell('');const badge=document.createElement('span');badge.className='status-badge status-'+normalStatus(item.status);badge.textContent=labels[item.status];statusCell.append(badge);const sms=(item.notifications?.at(-1)||item.staffAlert)?.channels.sms;if(sms){const line=document.createElement('small');line.className='sms-row-status';line.textContent='SMS: '+(smsLabels[sms.status]||sms.status);statusCell.append(line);}
    const actionCell=cell('');const actions=document.createElement('div');actions.className='request-row-actions';const review=document.createElement('button');review.type='button';review.className='review-button';review.textContent='Review ↗';review.setAttribute('aria-label','Review request from '+item.name);review.addEventListener('click',()=>openRequest(item));actions.append(review);
    for(const [status,label,className] of [['accepted','Confirm','accept-button'],['denied','Deny','deny-button']]){const button=document.createElement('button');button.type='button';button.className=className;button.textContent=label;button.setAttribute('aria-label',label+' request from '+item.name);button.disabled=status==='accepted'&&item.status==='completed';button.addEventListener('click',()=>prepareDecision(item,status));actions.append(button);}actionCell.append(actions);
    row.append(visitorCell,cell(reasonLabels[item.reason]),requested,dateCell,statusCell,actionCell);list.append(row);
  }
  byId('admin-empty').hidden=visible.length>0;byId('requests-list').closest('.request-table-wrap').hidden=visible.length===0;message('inbox-shown','Showing '+visible.length+' of '+requests.length+' requests');
}
function setFilter(value){statusFilter=value;renderRequests();}
function renderMessaging(settings){messaging=settings||messaging;message('messaging-banner',messaging.mode==='preview'?'SMS preview mode · Messages are prepared, but no text messages are sent.':messaging.sms?'SMS sending is configured · Check each request for its delivery status.':'SMS setup needed · Connect provider credentials and a sender to enable text messages.');}
async function refresh(){const button=byId('refresh-requests');button.disabled=true;message('admin-feedback','');try{const data=await api('/api/visits');requests=data.visits;renderMessaging(data.messaging);renderRequests();message('last-updated','Updated '+formattedDate(new Date(),{hour:'2-digit',minute:'2-digit'})+' · Central Time');}catch(error){message('admin-feedback',error.message);}finally{button.disabled=false;}}
function updateSmsPreview(){
  if(!activeRequest)return;const status=byId('request-status').value;const decision=['accepted','denied'].includes(status);byId('decision-sms-preview').hidden=!decision;
  if(!decision)return;
  const date=byId('decision-date').value;const time=byId('decision-time').value;const reason=byId('denial-reason').value.trim();
  const reasonSentence=/[.!?]$/.test(reason)?reason:reason+'.';
  let body=status==='denied'?(reason?`Fort Sam Houston Community Pharmacy: Your visit request was declined. Reason: ${reasonSentence} Ref ${activeRequest.reference}. Call (210) 295-9371 to discuss another time.`:'Enter the reason above to preview the visitor’s SMS.'):'Choose a confirmed date and time to preview the visitor’s SMS.';
  if(status==='accepted'&&date&&time){const dateText=formattedDate(date+'T12:00:00Z',{day:'numeric',month:'short',year:'numeric'});body=`Fort Sam Houston Community Pharmacy: Your visit is confirmed for ${dateText} at ${time} (Central Time). Ref ${activeRequest.reference}. Call (210) 295-9371 if plans change.`;}
  message('decision-sms-body',body);
  const permission=activeRequest.notificationChannels?.includes('sms');
  message('decision-sms-note',!permission?'This visitor did not agree to SMS updates. The decision is saved to Visit history.':messaging.mode==='preview'?'Preview only: no SMS will be sent. The decision is saved to Visit history.':!messaging.sms?'SMS setup is incomplete. The decision is saved and can be sent after setup.':'The message will be submitted to the SMS provider when you save this decision.');
}
function renderRequestMessages(){
  if(!activeRequest)return;const list=byId('request-message-list');list.replaceChildren();const events=[['Pharmacy alert',activeRequest.staffAlert],['Visitor update',activeRequest.notifications?.at(-1)]];
  for(const [label,event] of events){const card=document.createElement('article');card.className='sms-activity-card';const heading=document.createElement('strong');heading.textContent=label;card.append(heading);if(!event){const note=document.createElement('p');note.textContent=label==='Pharmacy alert'?'No alert was recorded for this older request.':'No confirmation or denial message has been prepared yet.';card.append(note);}else{const state=event.channels.sms;const badge=document.createElement('span');badge.className='sms-delivery-state';badge.textContent=smsLabels[state.status]||state.status;const body=document.createElement('p');body.textContent=event.body;card.append(badge,body);if(state.error){const note=document.createElement('small');note.textContent=state.error;card.append(note);}}list.append(card);}
  const states=events.map(([,event])=>event?.channels.sms).filter(Boolean);byId('check-sms').disabled=busy||messaging.mode!=='live'||!states.some(item=>item.providerId&&['queued','sending','sent'].includes(item.status));byId('retry-sms').disabled=busy||messaging.mode!=='live'||!messaging.sms||!states.some(item=>['preview','not_configured','failed'].includes(item.status));
}
async function loadDecisionTimes(){
  const sequence=++decisionSequence;const date=byId('decision-date').value;const time=byId('decision-time');const selected=date===activeRequest?.visitDate?activeRequest.visitTime:time.value;decisionTimesLoading=true;time.disabled=true;time.replaceChildren(new Option('Loading times…',''));byId('save-request-status').disabled=true;
  try{const data=await api('/api/availability'+(date?'?date='+encodeURIComponent(date):''));if(sequence!==decisionSequence)return;byId('decision-date').min=data.minDate;byId('decision-date').max=data.maxDate;const slots=[...(data.slots||[])];if(date===activeRequest?.visitDate&&activeRequest.status==='accepted'&&date>=data.minDate&&date<=data.maxDate&&!slots.includes(activeRequest.visitTime))slots.push(activeRequest.visitTime);slots.sort();time.replaceChildren(new Option(date?(slots.length?'Choose a time':'No times available'):'Choose a date first',''),...slots.map(slot=>new Option(slot,slot)));if(slots.includes(selected))time.value=selected;time.disabled=!slots.length;message('decision-schedule-help',slots.length?'The visitor’s confirmation uses this date and time, in Central Time.':'Choose a future date with an available time. Sundays are closed.');}catch(error){if(sequence===decisionSequence){time.replaceChildren(new Option('Times unavailable',''));message('decision-schedule-help',error.message);}}finally{if(sequence===decisionSequence){decisionTimesLoading=false;byId('save-request-status').disabled=false;updateSmsPreview();}}
}
function updateDecisionFields(loadTimes=true){
  const status=byId('request-status').value;const accepted=status==='accepted';const denied=status==='denied';byId('decision-schedule').hidden=!accepted;byId('denial-reason-box').hidden=!denied;byId('decision-date').required=accepted;byId('decision-time').required=accepted;byId('denial-reason').required=denied;byId('denial-reason').setCustomValidity('');
  const sends=messaging.mode==='live'&&messaging.sms&&activeRequest?.notificationChannels?.includes('sms');message('save-request-status',accepted?(sends?'Confirm & send SMS ↗':'Confirm visit ↗'):denied?(sends?'Deny & send SMS ↗':'Deny visit ↗'):'Save status ↗');
  if(accepted&&loadTimes)loadDecisionTimes();else if(!accepted){decisionSequence++;decisionTimesLoading=false;byId('save-request-status').disabled=busy;}
  updateSmsPreview();
}
function openRequest(item){activeRequest=item;message('request-dialog-title',item.name);message('request-dialog-reference',item.reference);message('detail-phone',item.phone);byId('detail-phone').href='tel:'+item.phone.replace(/[^+\d]/g,'');message('detail-reason',reasonLabels[item.reason]);message('detail-visit-time',item.visitDate?formattedDate(item.visitDate+'T12:00:00Z',{day:'numeric',month:'short',year:'numeric'})+' · '+item.visitTime+' (Central Time)':'Not supplied (older request)');message('detail-date',formattedDate(item.createdAt,{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})+' · Central Time');message('detail-current-status','Current status: '+labels[item.status]);byId('request-status').value=normalStatus(item.status);byId('decision-date').value=item.visitDate||'';byId('decision-time').replaceChildren(new Option(item.visitTime||'Choose a date first',item.visitTime||''));byId('denial-reason').value=item.denialReason||'';byId('accept-current-request').disabled=item.status==='completed';byId('deny-current-request').disabled=false;byId('delete-confirm').hidden=true;byId('request-status-form').hidden=false;message('request-detail-feedback','');message('sms-feedback','');updateDecisionFields();renderRequestMessages();if(!byId('request-dialog').open)byId('request-dialog').showModal();}
function prepareDecision(item,status){if(busy)return;if(activeRequest?.id!==item.id||!byId('request-dialog').open)openRequest(item);byId('request-status').value=status;updateDecisionFields();(status==='denied'?byId('denial-reason'):byId('decision-date')).focus();}
async function saveDecision(event){
  event.preventDefault();if(busy||decisionTimesLoading)return;const status=byId('request-status').value;const denial=byId('denial-reason');if(status==='denied')denial.setCustomValidity(denial.value.trim().length<10?'Please explain the reason in at least 10 characters.':'');if(!byId('request-status-form').reportValidity())return;
  if(status==='accepted'&&(!byId('decision-date').value||!byId('decision-time').value)){message('request-detail-feedback','Choose an available date and time before confirming this visit.');return;}
  busy=true;byId('save-request-status').disabled=true;message('request-detail-feedback','');
  try{const result=await api('/api/visits/'+activeRequest.id,{method:'PATCH',body:JSON.stringify({status,expectedUpdatedAt:activeRequest.updatedAt,...(status==='accepted'?{visitDate:byId('decision-date').value,visitTime:byId('decision-time').value}:{}),...(status==='denied'?{denialReason:denial.value.trim()}:{})})});byId('request-dialog').close();await refresh();const state=result.visit.notifications?.at(-1)?.channels.sms;message('admin-feedback','Visit '+labels[status].toLowerCase()+'. '+(state?'Visitor SMS: '+(smsLabels[state.status]||state.status)+'. ':'')+'The decision is visible in Visit history.');}catch(error){message('request-detail-feedback',error.message);}finally{busy=false;byId('save-request-status').disabled=false;}
}
async function smsAction(action){if(busy||!activeRequest)return;busy=true;renderRequestMessages();message('sms-feedback','');try{const result=await api('/api/visits/'+activeRequest.id+'/notifications/'+action,{method:'POST',body:'{}'});activeRequest=result.visit;renderMessaging(result.messaging);renderRequestMessages();message('sms-feedback',action==='check'?'Provider delivery status checked.':'Eligible SMS messages were submitted again. Check their delivery status.');}catch(error){message('sms-feedback',error.message);}finally{busy=false;renderRequestMessages();}}
byId('admin-login-form').addEventListener('submit',async event=>{
  event.preventDefault();if(busy)return;busy=true;const submit=event.currentTarget.querySelector('[type="submit"]');submit.disabled=true;message('login-status','');
  try{const session=await api('/api/session');csrf=session.csrf;const data=await api('/api/login',{method:'POST',body:JSON.stringify({username:byId('admin-username').value.trim(),password:byId('admin-password').value})});csrf=data.csrf;byId('admin-password').value='';showWorkspace(data.username);await refresh();}catch(error){message('login-status',error.message);}finally{busy=false;submit.disabled=false;}
});
byId('toggle-password').addEventListener('click',()=>{const field=byId('admin-password');const visible=field.type==='password';field.type=visible?'text':'password';byId('toggle-password').textContent=visible?'Hide':'Show';byId('toggle-password').setAttribute('aria-pressed',String(visible));});
byId('admin-logout').addEventListener('click',async()=>{try{await api('/api/logout',{method:'POST',body:'{}'});showLogin();message('login-status','You have signed out.');}catch(error){message('admin-feedback',error.message);}});
byId('refresh-requests').addEventListener('click',refresh);byId('request-search').addEventListener('input',renderRequests);
for(const button of document.querySelectorAll('[data-status-filter]'))button.addEventListener('click',()=>setFilter(button.dataset.statusFilter));
for(const button of document.querySelectorAll('[data-stat-filter]'))button.addEventListener('click',()=>setFilter(button.dataset.statFilter));
byId('clear-request-filters').addEventListener('click',()=>{byId('request-search').value='';setFilter('all');});
for(const button of document.querySelectorAll('[data-admin-view]'))button.addEventListener('click',()=>{const view=button.dataset.adminView;byId('requests-view').hidden=view!=='requests';byId('website-view').hidden=view!=='website';byId('reviews-view').hidden=view!=='reviews';message('admin-breadcrumb',{requests:'Visit requests',website:'Website overview',reviews:'Website reviews'}[view]);for(const link of document.querySelectorAll('[data-admin-view]')){link.classList.toggle('active',link===button);if(link===button)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');}});
byId('close-request').addEventListener('click',()=>byId('request-dialog').close());
byId('accept-current-request').addEventListener('click',()=>prepareDecision(activeRequest,'accepted'));
byId('deny-current-request').addEventListener('click',()=>prepareDecision(activeRequest,'denied'));
byId('request-status').addEventListener('change',()=>updateDecisionFields());
byId('decision-date').addEventListener('change',loadDecisionTimes);byId('decision-time').addEventListener('change',updateSmsPreview);byId('denial-reason').addEventListener('input',()=>{byId('denial-reason').setCustomValidity('');updateSmsPreview();});
byId('request-status-form').addEventListener('submit',saveDecision);
byId('check-sms').addEventListener('click',()=>smsAction('check'));byId('retry-sms').addEventListener('click',()=>smsAction('retry'));
byId('delete-request').addEventListener('click',()=>{byId('request-status-form').hidden=true;byId('delete-confirm').hidden=false;});
byId('cancel-delete').addEventListener('click',()=>{byId('request-status-form').hidden=false;byId('delete-confirm').hidden=true;});
byId('confirm-delete').addEventListener('click',async()=>{if(busy)return;busy=true;byId('confirm-delete').disabled=true;try{await api('/api/visits/'+activeRequest.id,{method:'DELETE',body:'{}'});byId('request-dialog').close();await refresh();message('admin-feedback','Request deleted.');}catch(error){byId('request-status-form').hidden=false;byId('delete-confirm').hidden=true;message('request-detail-feedback',error.message);}finally{busy=false;byId('confirm-delete').disabled=false;}});
async function initialise(){try{const session=await api('/api/session');csrf=session.csrf;if(new URLSearchParams(window.location.search).get('reauth')==='1'){const next=await api('/api/admin/reauth',{method:'POST',body:'{}'});csrf=next.csrf;showLogin();window.history.replaceState(null,'','admin.html');byId('admin-password').focus();return;}if(session.authenticated){showWorkspace(session.username);await refresh();}}catch(error){message('login-status',error.message);}}
initialise();
window.addEventListener('pageshow',event=>{if(event.persisted){showLogin();initialise();}});
